#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <dlfcn.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>

// Create a constructor function that will be executed when the library is loaded
__attribute__((constructor))
void init(void) {
    FILE *log_file = fopen("/tmp/hook_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "Hook loaded successfully!\n");

    // Get the path to the mystery_boi binary
    char proc_path[256];
    char bin_path[256];
    pid_t pid = getpid();

    sprintf(proc_path, "/proc/%d/exe", pid);
    ssize_t len = readlink(proc_path, bin_path, sizeof(bin_path) - 1);

    if (len != -1) {
        bin_path[len] = '\0';
        fprintf(log_file, "Binary path: %s\n", bin_path);

        // Copy the binary to a location we can access
        int src_fd = open(bin_path, O_RDONLY);
        if (src_fd != -1) {
            int dest_fd = open("/tmp/mystery_boi_copy", O_WRONLY | O_CREAT, 0755);
            if (dest_fd != -1) {
                char buffer[4096];
                ssize_t bytes_read;

                while ((bytes_read = read(src_fd, buffer, sizeof(buffer))) > 0) {
                    write(dest_fd, buffer, bytes_read);
                }

                close(dest_fd);
                fprintf(log_file, "Binary copied to /tmp/mystery_boi_copy\n");
            } else {
                fprintf(log_file, "Failed to create destination file\n");
            }
            close(src_fd);
        } else {
            fprintf(log_file, "Failed to open binary file\n");
        }
    } else {
        fprintf(log_file, "Failed to get binary path\n");
    }

    // Get environment variables
    char **env = environ;
    fprintf(log_file, "\nEnvironment variables:\n");
    while (*env) {
        fprintf(log_file, "%s\n", *env);
        env++;
    }

    fclose(log_file);
}

