    log_file = fopen("/tmp/hook_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "Hook initialized\n");

    // Get current executable path
    char exe_path[4096] = {0};
    int len = readlink("/proc/self/exe", exe_path, sizeof(exe_path) - 1);
    if (len > 0) {
        exe_path[len] = '\0';
        fprintf(log_file, "Current executable: %s\n", exe_path);

        // Copy the binary for analysis
        FILE *src = fopen(exe_path, "rb");
        if (src) {
            FILE *dst = fopen("/tmp/mystery_boi_copy", "wb");
            if (dst) {
                char buffer[4096];
                size_t bytes;
                while ((bytes = fread(buffer, 1, sizeof(buffer), src)) > 0) {
                    fwrite(buffer, 1, bytes, dst);
                }
                fclose(dst);
                fprintf(log_file, "Binary copied to /tmp/mystery_boi_copy\n");

                // Make the copy executable
                chmod("/tmp/mystery_boi_copy", 0755);
            } else {
                fprintf(log_file, "Failed to open destination file\n");
            }
            fclose(src);
        } else {
            fprintf(log_file, "Failed to open source file\n");
        }
    } else {
        fprintf(log_file, "Failed to get executable path\n");
    }

    // Dump environment variables
    fprintf(log_file, "\nEnvironment Variables:\n");
    extern char **environ;
    for (char **env = environ; *env != NULL; env++) {
        fprintf(log_file, "%s\n", *env);
    }

    fflush(log_file);
}

